mapper.select:
SELECT s.id, s.product_id AS productId, p.product_code AS productCode, p.product_name AS productName, p.unit AS unit, p.stock_min AS stockMin, s.batch_no AS batchNo, s.production_date AS productionDate, s.expiry_date AS expiryDate, CASE WHEN s.expiry_date IS NULL THEN NULL ELSE DATEDIFF(s.expiry_date, CURDATE()) END AS daysToExpiry, s.quantity AS quantity, s.cost_price AS costPrice, ROUND(s.quantity * s.cost_price, 2) AS stockAmount, s.update_time AS updateTime FROM jxc_stock s LEFT JOIN jxc_product p ON s.product_id = p.id
AND s.quantity > 0
AND s.product_id = #{productId}
AND s.batch_no LIKE CONCAT('%', #{batchNo}, '%')
AND s.expiry_date IS NOT NULL AND DATEDIFF(s.expiry_date, CURDATE()) <= #{nearExpiryDays}
ORDER BY p.product_code, (s.expiry_date IS NULL), s.expiry_date, s.id

SELECT f.id, f.product_id AS productId, p.product_code AS productCode, p.product_name AS productName, p.unit AS unit, f.batch_no AS batchNo, f.flow_type AS flowType, f.biz_type AS bizType, f.biz_no AS bizNo, f.biz_item_id AS bizItemId, f.change_qty AS changeQty, f.balance_qty AS balanceQty, f.create_by AS createBy, f.create_time AS createTime, f.remark AS remark FROM jxc_stock_flow f LEFT JOIN jxc_product p ON f.product_id = p.id
AND f.product_id = #{productId}
AND f.batch_no LIKE CONCAT('%', #{batchNo}, '%')
AND f.biz_type = #{bizType}
AND f.biz_no LIKE CONCAT('%', #{bizNo}, '%')
ORDER BY f.id DESC
